function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]))}
function toman(n){return Math.round(Number(n||0)).toLocaleString('fa-IR')+' تومان'}
function moneyUsd(n){return '$'+Number(n||0).toFixed(4)}
function csrf(req){if(!req.session.csrf)req.session.csrf=crypto.randomBytes(18).toString('hex');return req.session.csrf}
function checkCsrf(req,res,next){if(req.body?._csrf!==req.session.csrf)return res.status(403).send('Invalid request token');next()}
function base(title,body,{user=null,wide=false}={}){return `<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)} · Bavaan AI</title><meta name="description" content="API مدل‌های هوش مصنوعی به صورت PAYG"><link rel="stylesheet" href="/static/style.css?v=${esc(ASSET_VERSION)}"></head><body>${body}</body></html>`}
function publicHeader(user){return `<header class="sitehead"><a href="/" class="brand"><span class="brandmark">B</span><b>Bavaan AI</b></a><nav><a href="/models">مدل‌ها</a><a href="/pricing">قیمت‌گذاری</a><a href="/docs">مستندات</a></nav><div class="actions">${user?`<a class="btn ghost" href="/dashboard">داشبورد</a>`:`<a class="btn ghost" href="/login">ورود</a><a class="btn primary" href="/register">شروع رایگان</a>`}</div></header>`}
function flash(req){const x=req.session.flash;delete req.session.flash;return x?`<div class="flash ${x.type||''}">${esc(x.text)}</div>`:''}
function guard(req,res,next){if(!req.user)return res.redirect('/login');if(req.user.status==='suspended')return res.status(403).send('Account suspended');next()}
function adminGuard(req,res,next){if(!req.user)return res.redirect('/login');if(req.user.role!=='admin')return res.redirect('/dashboard');next()}
