app.post('/login',checkCsrf,async(req,res)=>{const {rows}=await pool.query('select * from users where email=$1',[String(req.body.email||'').toLowerCase()]);const u=rows[0];if(!u?.password_hash||!(await bcrypt.compare(String(req.body.password||''),u.password_hash))){req.session.flash={type:'error',text:'ایمیل یا رمز عبور درست نیست.'};return res.redirect('/login')}req.login(u,e=>e?res.status(500).send('Login failed'):res.redirect(u.onboarding_done?'/dashboard':'/onboarding'))});
